<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Http\Requests\StoreApplicationRequest;use App\Models\Application;use Illuminate\Http\JsonResponse;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class ApplicationController extends Controller{public function store(StoreApplicationRequest $r):JsonResponse{$application=DB::transaction(function()use($r){$data=$r->safe()->except(['transcript','identity_document','confirmation']);$data['reference']=(string)Str::uuid();$data['transcript_path']=$r->file('transcript')->store('applications/transcripts','local');$data['identity_document_path']=$r->file('identity_document')->store('applications/identity','local');$data['submitted_at']=now();return Application::create($data);});return response()->json(['message'=>'Application submitted successfully.','data'=>['reference'=>$application->reference,'status'=>$application->status]],201);}}
